/**
* Builds a hierarchical organizational tree from a flat list of employees.
*/
function buildOrgTree(employees, departments) {
	if (!employees || employees.length === 0) return null;
	const deptMap = /* @__PURE__ */ new Map();
	departments.forEach((d) => deptMap.set(d.id, d));
	let rootEmp = employees.find((e) => e.managerId === null);
	if (!rootEmp) rootEmp = employees.find((e) => e.id === "emp-ahmed-alabed") || employees[0];
	const buildSubtree = (emp, level) => {
		const children = employees.filter((e) => e.managerId === emp.id && e.id !== emp.id).sort((a, b) => a.order - b.order).map((child) => buildSubtree(child, level + 1));
		return {
			...emp,
			department: deptMap.get(emp.departmentId),
			children,
			level
		};
	};
	return buildSubtree(rootEmp, 0);
}
