function getDepartmentStats(employees, departments) {
	return departments.map((dept) => {
		const deptEmployees = employees.filter((e) => e.departmentId === dept.id);
		const confirmedCount = deptEmployees.filter((e) => e.isConfirmedPosition).length;
		return {
			department: dept,
			count: deptEmployees.length,
			confirmedCount
		};
	});
}
/**
* Validates employee input data for forms.
*/
function validateEmployee(data) {
	const errors = {};
	if (!data.nameAr || data.nameAr.trim().length < 2) errors.nameAr = "يرجى كتابة الاسم باللغة العربية (حرفان على الأقل)";
	if (!data.nameEn || data.nameEn.trim().length < 2) errors.nameEn = "يرجى كتابة الاسم باللغة الإنجليزية";
	if (!data.departmentId) errors.departmentId = "يرجى اختيار القسم التابع له";
	if (!data.jobTitleAr || data.jobTitleAr.trim().length < 2) errors.jobTitleAr = "يرجى تحديد المسمى الوظيفي بالعربية";
	return {
		isValid: Object.keys(errors).length === 0,
		errors
	};
}
/**
* Filters employee list by search term and department.
*/
function filterTeam(employees, searchTerm = "", departmentId = "all") {
	const cleanSearch = searchTerm.trim().toLowerCase();
	return employees.filter((emp) => {
		if (!(departmentId === "all" || emp.departmentId === departmentId)) return false;
		if (!cleanSearch) return true;
		const matchNameAr = emp.nameAr.toLowerCase().includes(cleanSearch);
		const matchNameEn = emp.nameEn.toLowerCase().includes(cleanSearch);
		const matchTitleAr = emp.jobTitleAr.toLowerCase().includes(cleanSearch);
		const matchTitleEn = emp.jobTitleEn.toLowerCase().includes(cleanSearch);
		return matchNameAr || matchNameEn || matchTitleAr || matchTitleEn;
	});
}
